// Dashboard page stub
import React, {
    useState,
    useEffect
} from 'react';
import {
    useNavigate
} from 'react-router-dom';

function Dashboard() {
    const [file, setFile] = useState(null);
    const [message, setMessage] = useState('');
    const [summaryRequested, setSummaryRequested] = useState(false);
    const [history, setHistory] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        const hist = JSON.parse(localStorage.getItem('summaryHistory') || '[]');
        setHistory(hist);
    }, []);

    const handleUpload = async (e) => {
        e.preventDefault();
        setMessage('');
        const formData = new FormData();
        formData.append('file', file);
        const res = await fetch('http://localhost:5000/api/upload', {
            method: 'POST',
            body: formData
        });
        const data = await res.json();
        if (data.success) {
            setMessage('File uploaded successfully');
        } else {
            setMessage('Upload failed');
        }
    };

    const handleSummary = async () => {
        setMessage('');
        setSummaryRequested(true);
        const res = await fetch('http://localhost:5000/api/summary', {
            method: 'POST'
        });
        const data = await res.json();
        if (data.summary) {
            localStorage.setItem('summary', JSON.stringify(data));
            // Save to history
            const hist = JSON.parse(localStorage.getItem('summaryHistory') || '[]');
            hist.push(data);
            localStorage.setItem('summaryHistory', JSON.stringify(hist));
            navigate('/summary');
        } else {
            setMessage('Summary request failed');
        }
        setSummaryRequested(false);
    };

    return ( <
        div >
        <
        h2 > Dashboard < /h2> <
        form onSubmit = {
            handleUpload
        } >
        <
        input type = "file"
        onChange = {
            e => setFile(e.target.files[0])
        }
        required / >
        <
        button type = "submit" > Upload Medical Record < /button> <
        /form> <
        button onClick = {
            handleSummary
        }
        disabled = {
            summaryRequested
        } > Request Summary < /button> {
            message && < p > {
                    message
                } < /p>} <
                h3 > Summary History < /h3> <
                ul > {
                    history.map((item, idx) => ( <
                        li key = {
                            idx
                        } > {
                            item.summary
                        } < span style = {
                            {
                                color: 'gray'
                            }
                        } > ({
                            item.confidence
                        }) < /span></li >
                    ))
                } <
                /ul> <
                /div>
        );
    }

    export default Dashboard;
